// Clear values from any earlier request in this run.
pm.variables.unset('userId');
pm.variables.unset('originalUser');

// 1. Validate status code.
pm.test('GET status code is 200', function () {
    pm.response.to.have.status(200);
});

const users = pm.response.json();

// 2. Validate response type and size.
pm.test('Response is a non-empty array', function () {
    pm.expect(users).to.be.an('array').that.is.not.empty;
});

// 3. Validate information for every user.
pm.test('Every user has a valid id, name and email', function () {
    pm.expect(users).to.be.an('array').that.is.not.empty;

    users.forEach(function (user) {
        pm.expect(user).to.have.property('id');
        pm.expect(user.id).to.be.a('number');
        pm.expect(user.id).to.be.above(0);

        pm.expect(user).to.have.property('name');
        pm.expect(user.name).to.be.a('string');
        pm.expect(user.name.trim()).to.not.equal('');

        pm.expect(user).to.have.property('email');
        pm.expect(user.email).to.be.a('string');
        pm.expect(user.email).to.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
    });
});

// 4. Select one user and save local variables.
pm.test('Save a selected user ID in a local variable', function () {
    pm.expect(pm.response.code).to.equal(200);
    pm.expect(users).to.be.an('array').that.is.not.empty;

    const selectedUser = users[0];

    pm.expect(selectedUser.id).to.be.a('number');
    pm.expect(selectedUser.id).to.be.above(0);

    pm.variables.set('userId', selectedUser.id);

    pm.variables.set(
        'originalUser',
        JSON.stringify(selectedUser)
    );

    pm.expect(pm.variables.get('userId')).to.equal(
        selectedUser.id
    );
});

// When PUT runs alone, fetch a user first.
if (
    !pm.variables.get('userId') ||
    !pm.variables.get('originalUser')
) {
    const response = await pm.sendRequest({
        url: pm.collectionVariables.get('baseUrl') + '/users',
        method: 'GET'
    });

    pm.test('Setup GET status code is 200', function () {
        pm.expect(response.code).to.equal(200);
    });

    if (response.code !== 200) {
        throw new Error('Could not fetch users for PUT setup');
    }

    const users = response.json();

    pm.test('Setup GET returns a non-empty user array', function () {
        pm.expect(users).to.be.an('array').that.is.not.empty;

        users.forEach(function (user) {
            pm.expect(user).to.have.property('id');
            pm.expect(user).to.have.property('name');
            pm.expect(user).to.have.property('email');
        });
    });

    if (!Array.isArray(users) || users.length === 0) {
        throw new Error('No users available for PUT setup');
    }

    const selectedUser = users[0];

    pm.variables.set('userId', selectedUser.id);
    pm.variables.set('originalUser', JSON.stringify(selectedUser));
}

// Read the original user.
const originalUser = JSON.parse(
    pm.variables.get('originalUser')
);

// Generate new values for this execution.
const uniqueValue = pm.variables.replaceIn('{{$guid}}');

const updatedName = 'Updated User ' + uniqueValue;
const updatedEmail = 'updated.' + uniqueValue + '@example.com';
const updatedCompanyName = 'Updated Company ' + uniqueValue;

pm.variables.set('updatedName', updatedName);
pm.variables.set('updatedEmail', updatedEmail);
pm.variables.set('updatedCompanyName', updatedCompanyName);

// Copy all original fields, then change only the required fields.
const updatedUser = JSON.parse(JSON.stringify(originalUser));

updatedUser.name = updatedName;
updatedUser.email = updatedEmail;
updatedUser.company.name = updatedCompanyName;

// Store the complete JSON request body.
pm.variables.set('updatedUserBody', JSON.stringify(updatedUser));

pm.test('PUT status code is 200', function () {
    pm.response.to.have.status(200);
});

const updatedUser = pm.response.json();

const originalUser = JSON.parse(
    pm.variables.get('originalUser')
);

pm.test('Returned ID matches the saved user ID', function () {
    pm.expect(updatedUser.id).to.equal(
        Number(pm.variables.get('userId'))
    );
});

pm.test('Phone is not empty and remains unchanged', function () {
    pm.expect(updatedUser.phone).to.be.a('string');
    pm.expect(updatedUser.phone.trim()).to.not.equal('');
    pm.expect(updatedUser.phone).to.equal(originalUser.phone);
});

pm.test('Returned name matches the updated name', function () {
    pm.expect(updatedUser.name).to.equal(
        pm.variables.get('updatedName')
    );

    pm.expect(updatedUser.name).to.not.equal(originalUser.name);
});

pm.test('Returned email matches the updated email', function () {
    pm.expect(updatedUser.email).to.equal(
        pm.variables.get('updatedEmail')
    );

    pm.expect(updatedUser.email).to.not.equal(originalUser.email);
});

pm.test('Returned company name matches the updated company name', function () {
    pm.expect(updatedUser.company.name).to.equal(
        pm.variables.get('updatedCompanyName')
    );

    pm.expect(updatedUser.company.name).to.not.equal(
        originalUser.company.name
    );
});

pm.test('All other user fields remain unchanged', function () {
    const expectedUser = JSON.parse(JSON.stringify(originalUser));

    expectedUser.name = pm.variables.get('updatedName');
    expectedUser.email = pm.variables.get('updatedEmail');
    expectedUser.company.name = pm.variables.get('updatedCompanyName');

    pm.expect(updatedUser).to.deep.equal(expectedUser);
});
